-- Trips within Ghana: where a trip can go, and the ways to get there
-- (owner, 3 Nov 2026: "add all the legit info you can find ... and create
-- the admin pages for me to do the rest"). Stays are already in (0099).
--
-- 1. destinations: a town or a sight a trip can go to. Where it is, the
--    town buses and flights arrive at (a lodge at Wli is reached through
--    Hohoe), the last leg from there, a short blurb in our own words, what
--    people go for, and a photo with its author and licence (Wikimedia
--    Commons: CC BY and CC BY-SA need the credit shown next to the photo).
--    Whether a destination is ready is worked out from its stays, its ways
--    there and the venues near it, not set by hand.
-- 2. intercity_routes: one row is one operator's service between two towns:
--    a bus class, a flight, a trotro. A fare is only ever one somebody read
--    or was told, with the date and where from; unknown is left blank.
--
-- Seeded (3 Nov 2026) with 26 destinations and 50 routes:
--   - places, coordinates and photos from Wikipedia, Wikimedia Commons and
--     OpenStreetMap (Wli falls, Tafi Atome); road distances by OSRM;
--   - VIP Jeoun's fares effective 8 April 2026, as Graphic Online printed
--     them (24 of its 42 executive routes and 18 of its 33 standard ones:
--     the rest were not published);
--   - Africa World Airlines' "from" fares off its site on 3 November 2026;
--   - PassionAir's routes, with no fares (it publishes none).
--
-- New tables follow 0080: RLS on, no policies, read and written by the
-- server only. Run npm run audit:smoke afterwards.

-- ── 1. destinations ─────────────────────────────────────────────────────
create table if not exists public.destinations (
  slug text primary key check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$' and char_length(slug) <= 40),
  name text not null check (char_length(name) between 2 and 80),
  region text not null check (region in (
    'Greater Accra', 'Ashanti', 'Western', 'Western North', 'Central', 'Eastern', 'Volta', 'Oti',
    'Northern', 'Savannah', 'North East', 'Upper East', 'Upper West', 'Bono', 'Bono East', 'Ahafo'
  )),
  -- The town it is in or by, as areas.city names it where we have one.
  town text check (town is null or char_length(town) <= 80),
  -- Where intercity buses and flights arrive: intercity_routes.to_town.
  gateway_town text not null check (char_length(gateway_town) between 2 and 80),
  last_leg text check (last_leg is null or char_length(last_leg) <= 200),
  lat double precision check (lat is null or lat between 4 and 12),
  lng double precision check (lng is null or lng between -4 and 2),
  -- Venues and stays within this of the point count as the destination's.
  radius_km numeric(5, 1) not null default 10 check (radius_km between 1 and 80),
  road_km_from_accra integer check (road_km_from_accra is null or road_km_from_accra between 0 and 1500),
  blurb text check (blurb is null or char_length(blurb) <= 300),
  highlights text[] not null default '{}',
  best_time text check (best_time is null or char_length(best_time) <= 200),
  hero_image text check (hero_image is null or char_length(hero_image) <= 1000),
  image_credit text check (image_credit is null or char_length(image_credit) <= 200),
  image_license text check (image_license is null or char_length(image_license) <= 60),
  image_source text check (image_source is null or char_length(image_source) <= 1000),
  wiki_url text check (wiki_url is null or char_length(wiki_url) <= 600),
  notes text check (notes is null or char_length(notes) <= 2000),
  is_active boolean not null default true,
  sort smallint not null default 0,
  updated_by uuid references auth.users (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists destinations_sort_idx on public.destinations (sort, name);

-- ── 2. ways between towns ──────────────────────────────────────────────
create table if not exists public.intercity_routes (
  id uuid primary key default gen_random_uuid(),
  from_town text not null default 'Accra' check (char_length(from_town) between 2 and 80),
  to_town text not null check (char_length(to_town) between 2 and 80),
  mode text not null check (mode in ('bus', 'trotro', 'car', 'flight', 'ferry')),
  operator text not null check (char_length(operator) between 2 and 80),
  -- "Executive", "Standard"; empty when the operator runs one kind.
  service text not null default '' check (char_length(service) <= 60),
  -- The fare applies the other way too, as a city-pair fare list gives it.
  both_ways boolean not null default true,
  from_station text check (from_station is null or char_length(from_station) <= 120),
  to_station text check (to_station is null or char_length(to_station) <= 120),
  departures text check (departures is null or char_length(departures) <= 200),
  duration_mins smallint check (duration_mins is null or duration_mins between 5 and 1800),
  fare_min_ghs numeric(10, 2) check (fare_min_ghs is null or fare_min_ghs >= 0),
  fare_max_ghs numeric(10, 2) check (fare_max_ghs is null or fare_max_ghs >= 0),
  book_url text check (book_url is null or char_length(book_url) <= 600),
  book_phone text check (book_phone is null or char_length(book_phone) <= 40),
  -- Where the fare came from: a fare list, an article, the operator's site.
  source_url text check (source_url is null or char_length(source_url) <= 600),
  notes text check (notes is null or char_length(notes) <= 500),
  checked_on date,
  is_active boolean not null default true,
  updated_by uuid references auth.users (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (from_town, to_town, mode, operator, service)
);

create index if not exists intercity_routes_to_idx on public.intercity_routes (to_town);
create index if not exists intercity_routes_from_idx on public.intercity_routes (from_town);

alter table public.destinations enable row level security;
alter table public.intercity_routes enable row level security;
revoke all on public.destinations from anon, authenticated;
revoke all on public.intercity_routes from anon, authenticated;
-- No policies: the admin writes and /api/trips reads, both as the server.

